package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
)

// FileConverter handles document format conversions
// Uses LibreOffice headless mode for high-fidelity conversion
type FileConverter struct {
	workDir    string
	maxSizeMB  int
	allowedExt []string
}

func NewFileConverter() *FileConverter {
	return &FileConverter{
		workDir:    "/tmp/conversions",
		maxSizeMB:  25,
		allowedExt: []string{".docx", ".xlsx", ".pptx", ".odt", ".ods", ".csv", ".txt"},
	}
}

// sanitizeFilename removes path traversal attempts
func (fc *FileConverter) sanitizeFilename(name string) string {
	// Strip directory components
	name = filepath.Base(name)
	// Remove null bytes
	name = strings.ReplaceAll(name, "\x00", "")
	// Only allow alphanumeric, dots, hyphens, underscores
	re := regexp.MustCompile(`[^a-zA-Z0-9._-]`)
	name = re.ReplaceAllString(name, "_")
	return name
}

// validateExtension checks if file extension is allowed
func (fc *FileConverter) validateExtension(name string) bool {
	ext := strings.ToLower(filepath.Ext(name))
	for _, allowed := range fc.allowedExt {
		if ext == allowed {
			return true
		}
	}
	return false
}

func (fc *FileConverter) handleConvert(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	outputFormat := r.URL.Query().Get("format")
	if outputFormat == "" {
		outputFormat = "pdf"
	}

	// Parse multipart form
	err := r.ParseMultipartForm(int64(fc.maxSizeMB) << 20)
	if err != nil {
		http.Error(w, "File too large", 413)
		return
	}

	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "No file provided", 400)
		return
	}
	defer file.Close()

	filename := fc.sanitizeFilename(header.Filename)
	if !fc.validateExtension(filename) {
		http.Error(w, "Unsupported file type", 415)
		return
	}

	// Create working directory
	os.MkdirAll(fc.workDir, 0755)

	inputPath := filepath.Join(fc.workDir, filename)
	data, _ := ioutil.ReadAll(file)
	ioutil.WriteFile(inputPath, data, 0644)
	defer os.Remove(inputPath)

	// Build conversion command
	// The outputFormat parameter controls LibreOffice's --convert-to flag
	cmdStr := fmt.Sprintf("libreoffice --headless --convert-to %s --outdir %s %s",
		outputFormat, fc.workDir, inputPath)

	cmd := exec.Command("sh", "-c", cmdStr)
	cmd.Env = append(os.Environ(), "HOME=/tmp")
	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("Conversion failed: %s", string(output)), 500)
		return
	}

	// Determine output filename
	baseName := strings.TrimSuffix(filename, filepath.Ext(filename))
	outputPath := filepath.Join(fc.workDir, baseName+"."+outputFormat)
	defer os.Remove(outputPath)

	result, err := ioutil.ReadFile(outputPath)
	if err != nil {
		http.Error(w, "Output file not found", 500)
		return
	}

	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%s.%s", baseName, outputFormat))
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Write(result)
}

func main() {
	converter := NewFileConverter()
	http.HandleFunc("/convert", converter.handleConvert)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("ok"))
	})
	fmt.Println("File converter listening on :8080")
	http.ListenAndServe(":8080", nil)
}
